\label{thm:wroth}
		Let $\mathfrak q=(q_0,q_1)$, $L=\operatorname{lcm}(q_0,q_1)$, let $S\subset M_k$ be finite and $\alpha_v\in\mathbb P^1_{\mathfrak q}(\overline{\mathbb Q})$ for $v\in S$. For every $\epsilon>0$ and $c\in\mathbb R$ there is a finite set $Z\subset\mathbb P^1(k)$ with
		\[
		\begin{aligned}
			\sum_{v\in S}-\log\delta_v(P,\alpha_v)
			&\le(2+\epsilon)\,L\,\mathfrak s_k(P)+c,
		\end{aligned}
		\]
		for all $P\in\mathbb P^1_{\mathfrak q}(k)$ with $\Phi(P)\notin Z$.

By Dirichlet's theorem \cite[Prop.~D.1.1]{HS2000} there are infinitely many coprime $(u,v)$ with $v\ge1$ and $|u/v-b|<v^{-2}$. Put $y=[u:v]$ and $M=\max\{|u|,|v|\}$, so $h(y)=\log M$ and $M\le(|b|+1)v$. Then
		\[
		\begin{aligned}
			\delta_\infty(y,[b:1])
			&=\frac{|u-bv|}{M\max\{|b|,1\}}
			<\frac{1}{vM\max\{|b|,1\}}\\
			&\le\frac{|b|+1}{\max\{|b|,1\}}M^{-2}
			\le2M^{-2}.
		\end{aligned}
		\]
		Choose $P$ with $\Phi(P)=y$ (Lemma~\ref{lem:fibres}(a)); then $h(y)=L\,\mathfrak s(P)$ and $\delta_\infty(P,\alpha)=\delta_\infty(y,[b:1])$.

\label{lem:integralpoints}
		\begin{enumerate}[(a)]
			\item Every $P\in\mathbb P^1_{\mathfrak q}(\mathbb Q)$ has a $\mathfrak q$-reduced representative $\mathbf x\in\mathbb Z^2$, unique up to $\mathbf x\mapsto(-1)\ast\mathbf x$. In particular $\mathcal S_{\mathbb Z}(P):=|\mathbf x|_{\mathfrak q}$ is well defined, and $\log\mathcal S_{\mathbb Z}(P)\ge\mathfrak s(P)$, with equality if and only if $P$ is integral.
			\item For $P\in\mathbb P^1_{\mathfrak q}(\mathbb Z)$ with coprime representative $\mathbf x$, we have $\Phi(P)=[x_0^{q_1}:x_1^{q_0}]$ with $\gcd(x_0^{q_1},x_1^{q_0})=1$. The map $\Phi$ is at most two-to-one on $\mathbb P^1_{\mathfrak q}(\mathbb Z)$, and its image consists of the $[u:v]\in\mathbb P^1(\mathbb Q)$ with $u,v$ coprime integers such that $\pm u$ is a $q_1$-th power and $\pm v$ is a $q_0$-th power.
			\item As $T\to\infty$, the number of $P\in\mathbb P^1_{\mathfrak q}(\mathbb Z)$ with $\mathfrak s(P)\le\log T$ is $\asymp T^{q_0+q_1}$, whereas the number of points $\Phi(P)$ with $P\in\mathbb P^1_{\mathfrak q}(\mathbb Q)$ and $\mathfrak s(P)\le\log T$ is $\asymp T^{2L}$.
		\end{enumerate}

\label{conj:radical}
		Let $G\in\mathbb Z[U,V]$ be a squarefree binary form of degree $d\ge1$ with $G(0,1)G(1,0)\neq0$, and let $\epsilon>0$. There is $C=C(\mathfrak q,G,\epsilon)>0$ such that
		\[
		\operatorname{rad}\bigl(G(x_0^{q_1},x_1^{q_0})\bigr)\ge C\,|\mathbf x|_{\mathfrak q}^{dL-q_0-q_1-\epsilon}
		\]
		for all coprime $\mathbf x\in\mathbb Z^2$ with $x_0x_1\,G(x_0^{q_1},x_1^{q_0})\neq0$.

\label{lem:radical}
		Assume the $abc$ conjecture. Let $\Psi\in\mathbb Z[U,V]$ be a binary form of degree $n$ without repeated factors, and let $\epsilon>0$. There is $c>0$ such that
		\[
		\operatorname{rad}\bigl(\Psi(u,v)\bigr)\ge c\max\{|u|,|v|\}^{n-2-\epsilon}
		\]
		for all coprime $(u,v)\in\mathbb Z^2$ with $\Psi(u,v)\neq0$.

\label{rem:abcgeneral}
		\begin{enumerate}[(a),leftmargin=*]
			\item The only point where the weights enter is the inequality $\operatorname{rad}(u)\operatorname{rad}(v)\le\mathcal S_{\mathbb Z}(P)^{q_0+q_1}$: the numerator and denominator of an integral point are perfect powers, so their radicals are small. Roth's method does not see radicals, and this is why it gives $2L$ instead of $q_0+q_1$.
			\item For $\mathfrak q=(1,1)$, Theorem~\ref{thm:abcgeneral} is the known implication from $abc$ to Roth's theorem over $\mathbb Q$ \cite{Bombieri1994,vF2002}.
			\item Theorem~\ref{thm:abcgeneral} is a special case of the radicalized form of Vojta's conjecture for curves, which follows from $abc$ \cite{vF2007}. For a stacky version of Vojta's conjecture that is equivalent to $abc$, see \cite{NX2025}. The point here is that, for integral points of $\mathbb P^1_{\mathfrak q}$, these inequalities specialize to the explicit exponent $q_0+q_1$, which is sharp by Proposition~\ref{prop:danilov}.
		\end{enumerate}

\label{def:wabc}
		Let $p,q\ge1$ be integers and $A,B$ nonzero integers. The \emph{weighted $abc$ conjecture} $\mathrm{wABC}(p,q;A,B)$ asserts that for every $\epsilon>0$ there is $K$ such that
		\[
		\max\{|x|^p,|y|^q\}\le K\bigl(|xy|\,\operatorname{rad}(Ax^p+By^q)\bigr)^{1+\epsilon}
		\]
		for all coprime integers $x,y$ with $xy(Ax^p+By^q)\neq0$.

Put $\varphi(\lambda)=\lambda^2-\lambda+1$, $\psi(\lambda)=(\lambda+1)(\lambda-2)(2\lambda-1)$ and $\omega(\lambda)=\lambda^2(\lambda-1)^2$. One checks the identity $4\varphi^3-\psi^2=27\omega$, so that $J=4\varphi^3/(27\omega)$ and $J-1=\psi^2/(27\omega)$. Hence $J$ has degree $6$, and its fibres are as follows:
		\begin{itemize}
			\item over $0$, the two zeros of $\varphi$, each with ramification index $3$;
			\item over $1$, the points $-1,\tfrac12,2$, each with index $2$;
			\item over $\infty$, the points $0,1,\infty$, each with index $2$.
		\end{itemize}
		Since $2\cdot6-2=4+3+3$, Riemann--Hurwitz shows that $J$ is unramified elsewhere. Now let $f=J\circ g$. It is unramified outside $J(\{0,1,\infty\})\cup\{0,1,\infty\}=\{0,1,\infty\}$. If $f(z)=0$, then $g(z)$ is a zero of $\varphi$, which does not lie in $\{0,1,\infty\}$, so $g$ is unramified at $z$ and $e_z(f)=3$. Likewise $e_z(f)=2$ for $z\in f^{-1}(1)$. Finally $f^{-1}(\infty)=g^{-1}(\{0,1,\infty\})\supset S$. For existence, replace $S$ by the finite Galois-stable set of all its conjugates. The prescribed-set form of Belyi's theorem \cite[Thm.~31.1]{Vojta2011} gives a map $g$ over $\mathbb Q$ with $S\subset g^{-1}(\{0,1,\infty\})$; the composition $J\circ g$ then has all points of $S$ over $\infty$, since $J(0)=J(1)=J(\infty)=\infty$.

\label{prop:metric}
		For Lebesgue-almost every $b\in\mathbb R$ and every $\epsilon>0$ there is $C=C(b,\epsilon)>0$ such that
		\[
		|x_0^{q_1}-b\,x_1^{q_0}|\ge C\,|\mathbf x|_{\mathfrak q}^{L-q_0-q_1-\epsilon}
		\]
		for all coprime $\mathbf x\in\mathbb Z^2$.

\label{cor:product}
		Let $\mathbf c_1,\dots,\mathbf c_t\in\overline{\mathbb Q}^{n+1}$ be in general position and $\epsilon>0$. There are $C>0$ and proper linear subspaces $W_1,\dots,W_u$ of $\mathbb P^n_{\mathbb Q}$ such that
		\[
		\prod_{j=1}^t|F_{\mathbf c_j}(\mathbf x)|\ge C\,|\mathbf x|_{\mathfrak q}^{L(t-n-1-\epsilon)}
		\]
		for every $\mathfrak q$-reduced $\mathbf x\in\mathbb Z^{n+1}$ with $\Phi([\mathbf x]_{\mathfrak q})\notin\bigcup_iW_i$ and $\prod_jF_{\mathbf c_j}(\mathbf x)\neq0$.

\label{thm:wthue}
		Let $F\in\overline{\mathbb Q}[X,Y]$ be weighted homogeneous, written as in Lemma~\ref{lem:structure} with $G$ free of repeated factors. For every $\epsilon>0$ there is $C>0$ such that
		\[
		|F(x,y)|\ge C\,|(x,y)|_{\mathfrak q}^{L(\kappa-2-\epsilon)}
		\]
		for all coprime $(x,y)\in\mathbb Z^2$ with $F(x,y)\neq0$.

\label{rem:sharpthue}
		\begin{enumerate}[(a),leftmargin=*]
			\item The hypothesis $\kappa\ge3$ cannot be weakened to $\kappa\ge2$ in general. For $\mathfrak q=(1,1)$ the Pell equation $u^2-2v^2=1$ has $\kappa=2$ and infinitely many solutions. For $\mathfrak q=(1,2)$ the form $X^2-Y$ has $\kappa=1$, and $x^2-y=1$ has the coprime solutions $(x,x^2-1)$.
			\item For coprime $p,q\ge2$ and $\mathfrak q=(q,p)$, the form $X^p-Y^q$ has $\kappa=1$, so Theorem~\ref{thm:wthue} alone gives no finiteness. Finiteness of $x^p-y^q=m$ follows from Siegel's theorem \cite{Siegel1929}, \cite[\S D.9]{HS2000}, as the curve has genus $(p-1)(q-1)/2\ge1$.
		\end{enumerate}

\label{cor:abcthue}
		Assume the $abc$ conjecture. Let $F$ be as in Theorem~\ref{thm:wthue}, and assume that $G(0,1)$ and $G(1,0)$ are nonzero. For every $\epsilon>0$,
		\[
		|F(x,y)|\gg_\epsilon|(x,y)|_{\mathfrak q}^{\kappa L-q_0-q_1-\epsilon}
		\]
		for all coprime $(x,y)\in\mathbb Z^2$ with $F(x,y)\neq0$. In particular, if $\kappa L>q_0+q_1$, then $F(x,y)=m$ has only finitely many coprime solutions for every $m\neq0$.
